[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'outlook-mailbox-cleanup.ps1') -Library
Import-Module (Join-Path $PSScriptRoot 'outlook-private-runtime.psm1') -Force
function Assert-SyntheticMode([bool]$Value,[string]$Name){if(-not $Value){throw "Synthetic restore mode test failed: $Name"}}
function New-SyntheticAttachment([byte[]]$Bytes,[string]$Name='fixture.txt'){$attachment=[pscustomobject]@{Bytes=$Bytes;FileName=$Name;Size=$Bytes.Length;Type=1};$attachment|Add-Member ScriptMethod SaveAsFile {param($Path);[IO.File]::WriteAllBytes($Path,$this.Bytes)};return $attachment}
function New-SyntheticCollection([string]$Kind,$Owner){$collection=[pscustomobject]@{Kind=$Kind;Owner=$Owner;Rows=[Collections.Generic.List[object]]::new()};$collection|Add-Member ScriptProperty Count {$this.Rows.Count};$collection|Add-Member ScriptMethod Item {param($Index)if($Index -lt 1 -or $Index -gt $this.Rows.Count){throw 'synthetic collection index outside range'};return $this.Rows[$Index-1]};$collection|Add-Member ScriptMethod Add {param($Value,$Type,$Position,$DisplayName)if($this.Kind -eq 'Folders'){$entry=New-SyntheticFolder ([string]$Value) ('folder-'+[guid]::NewGuid().ToString('N')) $this.Owner.StoreID $this.Owner;$this.Rows.Add($entry);return $entry};if($this.Kind -eq 'Items'){$entry=New-SyntheticItem $this.Owner;[void]$this.Rows.Add($entry);$script:SyntheticSourceItem=$entry;return $entry};if($this.Kind -eq 'Attachments'){$bytes=[IO.File]::ReadAllBytes([string]$Value);$entry=New-SyntheticAttachment $bytes ([string]$DisplayName);[void]$this.Rows.Add($entry);return $entry};throw 'unsupported synthetic collection'};return $collection}
function New-SyntheticFolder([string]$Name,[string]$Id,[string]$StoreId,$Parent){$folder=[pscustomobject]@{Name=$Name;EntryID=$Id;StoreID=$StoreId;Parent=$Parent;Items=$null;Folders=$null};$folder.Items=New-SyntheticCollection 'Items' $folder;$folder.Folders=New-SyntheticCollection 'Folders' $folder;return $folder}
function New-SyntheticItem($Parent){$item=[pscustomobject]@{Class=43;EntryID='item-'+[guid]::NewGuid().ToString('N');Subject='Synthetic cleanup restore fixture';Body="Synthetic body for offline round-trip validation.`r`nNo owner or production content.";SenderEmailAddress='';InternetMessageID='';ConversationID='';ReceivedTime=[datetime]'2026-10-01T12:00:00Z';LastModificationTime=[datetime]'2026-10-01T12:00:00Z';UnRead=$true;FlagStatus=2;Categories='Synthetic cleanup test';Sent=$true;Parent=$Parent;Attachments=$null;PropertyAccessor=$null};$item.Attachments=New-SyntheticCollection 'Attachments' $item;$item.PropertyAccessor=New-SyntheticAccessor $item;$item|Add-Member ScriptMethod Save {};$item|Add-Member ScriptMethod SaveAs {param($Path,$Format);[IO.File]::WriteAllBytes($Path,[Text.Encoding]::Unicode.GetBytes('synthetic-msg-fixture'))};$item|Add-Member ScriptMethod Move {param($Destination);if($this.Parent -and $this.Parent.Items){[void]$this.Parent.Items.Rows.Remove($this)};$this.Parent=$Destination;[void]$Destination.Items.Rows.Add($this);return $this};return $item}
function New-SyntheticAccessor($Item){$accessor=[pscustomobject]@{Item=$Item;Values=@{}};$accessor|Add-Member ScriptMethod SetProperty {param($Name,$Value);$this.Values[$Name]=$Value};$accessor|Add-Member ScriptMethod GetProperty {param($Name);if($this.Values.ContainsKey($Name)){return $this.Values[$Name]};if($Name -eq 'http://schemas.microsoft.com/mapi/proptag/0x0E070003'){return 0};throw 'unknown synthetic property'};return $accessor}
function Copy-SyntheticMsg($Item){$copy=New-SyntheticItem $Item.Parent;$copy.Subject=$Item.Subject;$copy.Body=if($script:SyntheticMismatch -eq 'body'){'changed body'}else{$Item.Body};$copy.ReceivedTime=$Item.ReceivedTime;$copy.UnRead=$Item.UnRead;$copy.FlagStatus=$Item.FlagStatus;$copy.Categories=$Item.Categories;$copy.Sent=$Item.Sent;foreach($attachment in $Item.Attachments.Rows){$bytes=if($script:SyntheticMismatch -eq 'attachment'){[Text.Encoding]::UTF8.GetBytes('changed attachment')}else{$attachment.Bytes};$copy.Attachments.Rows.Add((New-SyntheticAttachment $bytes $attachment.FileName))};return $copy}
function New-SyntheticOutlookWorld {
  $script:SyntheticStoreId='fixture-store-'+[guid]::NewGuid().ToString('N');$root=New-SyntheticFolder 'Fixture PST' 'fixture-pst-root' $script:SyntheticStoreId $null;$store=[pscustomobject]@{StoreID=$script:SyntheticStoreId;FilePath='';Root=$root};$store|Add-Member ScriptMethod GetRootFolder {return $this.Root};$root.StoreID=$store.StoreID
  $primary=[pscustomobject]@{StoreID='primary-store';FilePath=''};$primaryAccount=[pscustomobject]@{SmtpAddress='fixture@example.invalid';DeliveryStore=$primary}
  $accounts=[pscustomobject]@{Rows=[Collections.Generic.List[object]]::new()};$accounts.Rows.Add($primaryAccount);$accounts|Add-Member ScriptProperty Count {$this.Rows.Count};$accounts|Add-Member ScriptMethod Item {param($Index)return $this.Rows[$Index-1]}
  $stores=[pscustomobject]@{Rows=[Collections.Generic.List[object]]::new()};$stores|Add-Member ScriptProperty Count {$this.Rows.Count};$stores|Add-Member ScriptMethod Item {param($Index)return $this.Rows[$Index-1]}
  $namespace=[pscustomobject]@{Stores=$stores;Accounts=$accounts;FixtureStore=$null};$namespace|Add-Member ScriptMethod GetNamespace {param($Name)return $this};$namespace|Add-Member ScriptMethod AddStoreEx {param($Path,$Type);$this.FixtureStore.FilePath=$Path;[IO.File]::WriteAllBytes($Path,[byte[]](0));[void]$this.Stores.Rows.Add($this.FixtureStore)};$namespace|Add-Member ScriptMethod RemoveStore {param($Folder);for($i=$this.Stores.Rows.Count-1;$i -ge 0;$i--){if($this.Stores.Rows[$i].StoreID -eq $Folder.StoreID){$this.Stores.Rows.RemoveAt($i)}}};$namespace|Add-Member ScriptMethod OpenSharedItem {param($Path)return (Copy-SyntheticMsg $script:SyntheticSourceItem)};$namespace.FixtureStore=$store
  $app=[pscustomobject]@{Namespace=$namespace};$app|Add-Member ScriptMethod GetNamespace {param($Name)return $this.Namespace};return [pscustomobject]@{Application=$app;Namespace=$namespace;Store=$store;Root=$root}
}
function New-SyntheticMutex{$mutex=[pscustomobject]@{Released=$false;Disposed=$false};$mutex|Add-Member ScriptMethod WaitOne {param($Timeout)return $true};$mutex|Add-Member ScriptMethod ReleaseMutex {$this.Released=$true};$mutex|Add-Member ScriptMethod Dispose {$this.Disposed=$true};return $mutex}
function Enter-MaintenanceCoordinator {param($Context);$lease=[pscustomobject]@{Acquired=$true;GateEnabled=$true};$lease|Add-Member ScriptMethod Dispose {};return $lease}

$testState=Join-Path ([IO.Path]::GetTempPath()) ('cleanup-synthetic-mode-'+[guid]::NewGuid().ToString('N'))
$script:StateRoot=$testState;$script:Mailbox='fixture@example.invalid';$script:RuntimeContextFactory={param($Root,$Environment,$Binding,$Version);New-PrivateRuntimeContext -StateRoot $Root -Environment $Environment -MailboxBinding $Binding -ConfigVersion $Version -ProtectBytes {param($Bytes,$Entropy);return ,[Text.Encoding]::UTF8.GetBytes([Convert]::ToBase64String($Bytes))} -UnprotectBytes {param($Bytes,$Entropy);return ,[Convert]::FromBase64String([Text.Encoding]::UTF8.GetString($Bytes))}}
$script:SyntheticMutexFactory={New-SyntheticMutex};$script:SyntheticMismatch='';$script:SyntheticSourceItem=$null;$script:SyntheticNamespaceFactory=$null
try {
  [IO.Directory]::CreateDirectory($testState)|Out-Null;$successWorld=New-SyntheticOutlookWorld;$script:OutlookFactory={return $successWorld.Application};$script:SyntheticSourceItem=$null
  $success=Invoke-SyntheticRestore;$proofContext=New-CleanupRuntimeContext $testState 'outlook-cleanup' (Get-StringHash $script:Mailbox.ToLowerInvariant()) 'cleanup-v1';$accepted=Read-ProtectedJson -Path (Join-Path $testState 'synthetic-restore-proof.dpapi') -Context $proofContext
  Assert-SyntheticMode ($success.SyntheticRestoreVerified -and $accepted.cleanupFinalized -and $successWorld.Namespace.Stores.Count -eq 0) 'synthetic PST round-trip verifies message, attachment, state, detach, and final cleanup before acceptance'
  Remove-Item -LiteralPath (Join-Path $testState 'synthetic-restore-proof.dpapi') -Force

  $pendingWorld=New-SyntheticOutlookWorld;$script:OutlookFactory={return $pendingWorld.Application};$script:SyntheticSourceItem=$null
  $script:SyntheticCleanupRemover={param($Root,$Context);return $false};$pending=Invoke-SyntheticRestore;$pendingReceipt=Read-ProtectedJson -Path (Join-Path $testState 'pending-synthetic-restore.dpapi') -Context $proofContext
  Assert-SyntheticMode ($pending.Phase -eq 'cleanup_pending' -and -not $pending.Accepted -and -not [bool]$pendingReceipt.accepted -and -not(Test-Path -LiteralPath (Join-Path $testState 'synthetic-restore-proof.dpapi')) -and $pendingWorld.Namespace.Stores.Count -eq 0) 'cleanup failure after verified/detached PST creates only an unaccepted protected pending receipt'
  $script:SyntheticNamespaceFactory={return [pscustomobject]@{Namespace=$pendingWorld.Namespace;Application=$null}};$script:SyntheticCleanupRemover={param($Root,$Context);$validated=Test-SyntheticRunPath $Root $Context;Remove-Item -LiteralPath $validated -Recurse -Force;return (-not(Test-Path -LiteralPath $validated))};$final=Invoke-FinalizeSyntheticRestore;$finalProof=Read-ProtectedJson -Path (Join-Path $testState 'synthetic-restore-proof.dpapi') -Context $proofContext
  Assert-SyntheticMode ($final.Accepted -and $finalProof.cleanupFinalized -and -not(Test-Path -LiteralPath (Join-Path $testState 'pending-synthetic-restore.dpapi'))) 'deferred cleanup finalizer accepts only after exact isolated PST files are removed'

  Remove-Item -LiteralPath (Join-Path $testState 'synthetic-restore-proof.dpapi') -Force
  $mismatchWorld=New-SyntheticOutlookWorld;$script:OutlookFactory={return $mismatchWorld.Application};$script:SyntheticSourceItem=$null;$script:SyntheticMismatch='attachment';$script:SyntheticCleanupRemover=$null;$mismatchRejected=$false;try{Invoke-SyntheticRestore}catch{$mismatchRejected=$true}
  Assert-SyntheticMode ($mismatchRejected -and -not(Test-Path -LiteralPath (Join-Path $testState 'synthetic-restore-proof.dpapi')) -and -not(Test-Path -LiteralPath (Join-Path $testState 'pending-synthetic-restore.dpapi')) -and $mismatchWorld.Namespace.Stores.Count -eq 0) 'changed restored attachment bytes reject synthetic proof and clean the fixture'
  Write-Output 'Synthetic Outlook restore mode tests passed.'
} finally {if(Test-Path -LiteralPath $testState){Remove-Item -LiteralPath $testState -Recurse -Force};$script:OutlookFactory=$null;$script:RuntimeContextFactory=$null;$script:SyntheticNamespaceFactory=$null;$script:SyntheticCleanupRemover=$null;$script:SyntheticMutexFactory=$null;$script:SyntheticSourceItem=$null;$script:SyntheticMismatch=''}
